import 'package:path/path.dart' as p;
import 'package:sqflite/sqflite.dart';
class LocalDatabase { static final LocalDatabase instance=LocalDatabase._(); LocalDatabase._(); Database? _database; Future<Database> get database async {if(_database!=null)return _database!;final path=p.join(await getDatabasesPath(),'dtt_finance.db');_database=await openDatabase(path,version:2,onCreate:(db,version)async{await db.execute('CREATE TABLE accounts(id TEXT PRIMARY KEY, name TEXT NOT NULL, opening_balance INTEGER NOT NULL)');await db.execute('CREATE TABLE categories(id TEXT PRIMARY KEY, name TEXT NOT NULL, type TEXT NOT NULL)');await db.execute('CREATE TABLE transactions(id TEXT PRIMARY KEY, account_id TEXT NOT NULL, destination_account_id TEXT, amount INTEGER NOT NULL, type TEXT NOT NULL, category_id TEXT NOT NULL, note TEXT NOT NULL, date TEXT NOT NULL, status TEXT NOT NULL, batch_id TEXT)');await db.execute('CREATE TABLE audit_log(id INTEGER PRIMARY KEY AUTOINCREMENT, action TEXT NOT NULL, entity_id TEXT NOT NULL, created_at TEXT NOT NULL)');await db.execute('CREATE TABLE journal_lines(id INTEGER PRIMARY KEY AUTOINCREMENT, transaction_id TEXT NOT NULL, account_id TEXT NOT NULL, debit INTEGER NOT NULL, credit INTEGER NOT NULL)');},onUpgrade:(db,oldVersion,newVersion)async{if(oldVersion<2)await db.execute('ALTER TABLE transactions ADD COLUMN destination_account_id TEXT');});return _database!;} }
